+const quizForm = document.getElementById('quizForm');
+const resultDiv = document.getElementById('result');
+const formError = document.getElementById('form-error');
+
+quizForm.addEventListener('submit', function(e) {
+  e.preventDefault();
+
+  // Clear previous errors
+  formError.hidden = true;
+  let hasErrors = false;
+
+  // Validate each question (at least one answer must be selected)
+  for (let i = 1; i <= 3; i++) {
+    const errorEl = document.getElementById(`q${i}-error`);
+    const checkboxes = document.querySelectorAll(`input[name="q${i}"]`);
+    const isChecked = Array.from(checkboxes).some(cb => cb.checked);
+
+    if (!isChecked) {
+      errorEl.textContent = 'Error: Please select at least one answer.';
+      errorEl.hidden = false;
+      hasErrors = true;
+
+      // Focus on first checkbox of this question if it's the first error
+      if (!hasErrors || i === 1) {
+        checkboxes[0].focus();
+      }
+    } else {
+      errorEl.hidden = true;
+    }
+  }
+
+  if (hasErrors) {
+    formError.textContent = 'Please answer all questions before submitting.';
+    formError.hidden = false;
+    return;
+  }
+
+  // Collect answers
+  const answers = {};
+  for (let i = 1; i <= 3; i++) {
+    const checkboxes = document.querySelectorAll(`input[name="q${i}"]`);
+    answers[`q${i}`] = Array.from(checkboxes)
+      .filter(cb => cb.checked)
+      .map(cb => cb.value);
+  }
+
+  // Log or process answers
+  console.log('Quiz Answers:', answers);
+
+  // Hide form and show result
+  quizForm.hidden = true;
+  resultDiv.hidden = false;
+  resultDiv.scrollIntoView({ behavior: 'smooth' });
+
+  // Announce success to screen readers
+  resultDiv.setAttribute('role', 'status');
+  resultDiv.setAttribute('aria-live', 'polite');
